#include "homebrew_test_runtime.h"
#include "homebrew/funcs.h"       // Generated by SwitchGamesRecomp.
#include "homebrew_fixture.h"     // Extracted from our own cross-compiled C ELF.
#include <array>
#include <cerrno>
#include <cstddef>
#include <cstdint>
#include <cstring>
#include <stdexcept>
#include <sys/mman.h>

#ifndef MAP_FIXED_NOREPLACE
#define MAP_FIXED_NOREPLACE 0x100000
#endif

namespace {
thread_local uint32_t svc_calls=0;

class GuestMap {
  void* allocated_=MAP_FAILED;
public:
  GuestMap() {
    // Never overwrite Android's existing mappings, and never mark guest memory executable.
    void* desired=reinterpret_cast<void*>(static_cast<uintptr_t>(NX_BASE));
    allocated_=mmap(desired,homebrew_fixture::kMapBytes,PROT_READ|PROT_WRITE,
                    MAP_PRIVATE|MAP_ANONYMOUS|MAP_FIXED_NOREPLACE,-1,0);
    if(allocated_==MAP_FAILED && errno==EINVAL) {
      // Older kernels: use non-destructive address hint, reject wrong addresses.
      allocated_=mmap(desired,homebrew_fixture::kMapBytes,PROT_READ|PROT_WRITE,
                      MAP_PRIVATE|MAP_ANONYMOUS,-1,0);
      if(allocated_!=MAP_FAILED && allocated_!=desired) {
        munmap(allocated_,homebrew_fixture::kMapBytes);
        allocated_=MAP_FAILED;
      }
    }
    if(allocated_==MAP_FAILED)
      throw std::runtime_error("Guest memory at NX_BASE not available (non-destructive map)");
    if(allocated_!=desired) {
      munmap(allocated_,homebrew_fixture::kMapBytes);
      allocated_=MAP_FAILED;
      throw std::runtime_error("Guest memory address is not the expected NX_BASE");
    }
    // Real bytes are from our cross-compiled ELF. The BSS comes from mmap's zero fill.
    std::memcpy(reinterpret_cast<void*>(NX_BASE+homebrew_fixture::kTextOffset),
                homebrew_fixture::kText,sizeof(homebrew_fixture::kText));
    std::memcpy(reinterpret_cast<void*>(NX_BASE+homebrew_fixture::kRoOffset),
                homebrew_fixture::kRo,sizeof(homebrew_fixture::kRo));
    std::memcpy(reinterpret_cast<void*>(NX_BASE+homebrew_fixture::kDataOffset),
                homebrew_fixture::kData,sizeof(homebrew_fixture::kData));
  }
  GuestMap(const GuestMap&)=delete;
  GuestMap& operator=(const GuestMap&)=delete;
  ~GuestMap(){if(allocated_!=MAP_FAILED)munmap(allocated_,homebrew_fixture::kMapBytes);}
  uint32_t counter() const {
    uint32_t n=0;
    std::memcpy(&n,reinterpret_cast<void*>(NX_BASE+homebrew_fixture::kBssOffset),sizeof(n));
    return n;
  }
};

uint32_t expected(uint32_t seed,uint32_t invocation) {
  uint32_t total=0;
  for(uint32_t i=0;i<4;i++) {
    const uint32_t value=seed+3u*i, round=i+1u;
    total+=(value^(round*3u))+(round<<2u);
  }
  // Our synthetic SVC #0x7e adds 11, then the code reads initialized guest globals.
  return ((total^seed)+11u)+3u+11u+invocation;
}

uint32_t invoke(uint32_t seed) {
  alignas(16) std::array<unsigned char,16384> stack{};
  nx::CPU c{};
  c.x[31]=(reinterpret_cast<uintptr_t>(stack.data()+stack.size())) & ~uintptr_t(15);
  c.x[0]=seed;
  homebrew_00000040(c);   // Function emitted by actual upstream ARM64->C++ recompiler.
  return static_cast<uint32_t>(c.x[0]);
}
} // namespace

// This is a NON-HORIZON, internal test service. Real Horizon IPC is NOT implemented.
namespace nx {
void svc(CPU& c,uint32_t imm,uint64_t) {
  if(imm!=0x7e) throw std::runtime_error("Unsupported SVC from test executable");
  ++svc_calls;
  c.x[0]=static_cast<uint32_t>(c.x[0])+11u;
}
[[noreturn]] void unimpl(CPU&,uint64_t,const char*) {
  throw std::runtime_error("Untranslated ARM64 instruction");
}
}

namespace homebrew_test {
Result run(){
  Result r;
  try {
    GuestMap mem;
    svc_calls=0;
    r.got_first=invoke(7);
    r.expected_first=expected(7,1);
    r.got_second=invoke(19);
    r.expected_second=expected(19,2);
    r.final_guest_counter=mem.counter();
    r.service_calls=svc_calls;
    r.ok=r.got_first==r.expected_first&&r.got_second==r.expected_second&&
         r.final_guest_counter==2&&r.service_calls==2;
    if(!r.ok)r.diagnostic="ARM64 guest result differs from native C reference";
  } catch(const std::exception& e) {
    r.ok=false;
    r.diagnostic=e.what();
  }
  return r;
}
}
